section.code:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://faion.net/schemas/csharp-entity-framework.json",
  "type": "object",
  "required": ["dbcontext_name", "provider", "entities", "asnotracking_audit", "concurrency_audit", "audit_interceptor", "migration_sql_reviewed"],
  "properties": {
    "dbcontext_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+DbContext$"},
    "provider": {"enum": ["Npgsql", "SqlServer", "Sqlite"]},
    "entities": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name", "configuration_class", "is_aggregate_root"],
        "properties": {
          "name": {"type": "string"},
          "configuration_class": {"type": "string", "pattern": "Configuration$"},
          "is_aggregate_root": {"type": "boolean"},
          "concurrency_token_field": {"type": "string"},
          "has_public_setters": {"type": "boolean", "const": false},
          "data_annotations_present": {"type": "boolean", "const": false}
        }
      },
      "minItems": 1
    },
    "asnotracking_audit": {"type": "object", "required": ["read_paths_pass"], "properties": {"read_paths_pass": {"type": "boolean", "const": true}}},
    "concurrency_audit": {"type": "object", "required": ["aggregates_have_token"], "properties": {"aggregates_have_token": {"type": "boolean", "const": true}}},
    "audit_interceptor": {"type": "object", "required": ["registered"], "properties": {"registered": {"type": "boolean", "const": true}}},
    "repositories": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["class_name", "list_uses_asnotracking", "returns_iqueryable"],
        "properties": {
          "class_name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+Repository$"},
          "list_uses_asnotracking": {"type": "boolean", "const": true},
          "returns_iqueryable": {"type": "boolean", "const": false},
          "multi_collection_split_query": {"type": "boolean", "const": true},
          "list_return_type": {"type": "string", "pattern": "^PagedResult<"}
        }
      }
    },
    "migration": {
      "type": "object",
      "required": ["name", "appended"],
      "properties": {
        "name": {"type": "string", "pattern": "^[A-Z][A-Za-z0-9]+$"},
        "appended": {"type": "boolean", "const": true}
      }
    },
    "migration_sql_reviewed": {"type": "boolean", "const": true},
    "forbidden_patterns_found": {"type": "array", "items": {"type": "string"}, "maxItems": 0}
  }
}

example.code:
{
  "dbcontext_name": "BillingDbContext",
  "provider": "Npgsql",
  "entities": [
    {"name": "Invoice", "configuration_class": "InvoiceConfiguration", "is_aggregate_root": true,
     "concurrency_token_field": "xmin", "has_public_setters": false, "data_annotations_present": false},
    {"name": "InvoiceLine", "configuration_class": "InvoiceLineConfiguration", "is_aggregate_root": false,
     "has_public_setters": false, "data_annotations_present": false}
  ],
  "repositories": [
    {"class_name": "InvoiceRepository", "list_uses_asnotracking": true, "returns_iqueryable": false,
     "multi_collection_split_query": true, "list_return_type": "PagedResult<InvoiceDto>"}
  ],
  "migration": {"name": "AddInvoicesTable", "appended": true},
  "asnotracking_audit": {"read_paths_pass": true},
  "concurrency_audit": {"aggregates_have_token": true},
  "audit_interceptor": {"registered": true},
  "migration_sql_reviewed": true,
  "forbidden_patterns_found": []
}

{
  "dbcontext_name": "billing_db",
  "provider": "MariaDB",
  "entities": [
    {"name": "invoice", "configuration_class": "InvoiceConfig", "is_aggregate_root": true,
     "has_public_setters": true, "data_annotations_present": true}
  ],
  "repositories": [
    {"class_name": "InvoiceRepo", "list_uses_asnotracking": false, "returns_iqueryable": true,
     "multi_collection_split_query": false, "list_return_type": "IQueryable<Invoice>"}
  ],
  "migration": {"name": "fix_typo", "appended": false},
  "asnotracking_audit": {"read_paths_pass": false},
  "concurrency_audit": {"aggregates_have_token": false},
  "audit_interceptor": {"registered": false},
  "migration_sql_reviewed": false,
  "forbidden_patterns_found": ["IQueryable<Invoice> returned from InvoiceRepository.Query"]
}
